import{_ as a}from"./chunks/gep23-design-outline.DnBhQwI5.js";import{_ as i,c as t,o,a2 as s}from"./chunks/framework.QTfwLiL8.js";const f=JSON.parse('{"title":"0023 Autoscaling Kube Apiserver Via Independent Hpa And Vpa","description":"","frontmatter":{"github_repo":"https://github.com/gardener/enhancements","github_subdir":"geps/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa","params":{"github_branch":"main"},"path_base_for_github_subdir":{"from":"content/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/README.md","to":"README.md"},"title":"0023 Autoscaling Kube Apiserver Via Independent Hpa And Vpa","prev":false,"next":false},"headers":[],"relativePath":"docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/_index.md","filePath":"docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/_index.md","lastUpdated":null}'),n={name:"docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/_index.md"};function r(l,e,c,d,p,u){return o(),t("div",null,e[0]||(e[0]=[s('<h1 id="gep-0023-autoscaling-shoot-kube-apiserver-via-independently-driven-hpa-and-vpa" tabindex="-1">GEP-0023: Autoscaling Shoot kube-apiserver via Independently Driven HPA and VPA <a class="header-anchor" href="#gep-0023-autoscaling-shoot-kube-apiserver-via-independently-driven-hpa-and-vpa" aria-label="Permalink to &quot;GEP-0023: Autoscaling Shoot kube-apiserver via Independently Driven HPA and VPA&quot;">​</a></h1><p>📌 <strong>Replacement Notice</strong></p><p>The GEP is replaced by an autoscaling solution for Kubernetes API server based on native HPA and VPA resources. Kubernetes API server is scaled simultaneously by HPA and VPA on the same metric (CPU and memory usage). For more details, see the <a href="https://github.com/gardener/gardener/tree/master/docs/development/autoscaling-specifics-for-components.md" target="_blank" rel="noreferrer">Autoscaling Specifics for Components documentation</a>. The implementation PR of the replacement feature is <a href="https://github.com/gardener/gardener/pull/9678" target="_blank" rel="noreferrer">gardener/gardener#9678</a>.</p><hr><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#gep-0023-autoscaling-shoot-kube-apiserver-via-independently-driven-hpa-and-vpa">GEP-0023: Autoscaling Shoot kube-apiserver via Independently Driven HPA and VPA</a><ul><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#table-of-contents">Table of Contents</a></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#summary">Summary</a></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#motivation">Motivation</a><ul><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#existing-solution">Existing Solution</a></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#deficiencies-of-the-existing-solution">Deficiencies of the Existing Solution</a></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#other-benefits-to-replacing-the-existing-solution">Other Benefits to Replacing the Existing Solution</a></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#goals">Goals</a></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#non-goals">Non-Goals</a></li></ul></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#proposal">Proposal</a><ul><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#rationale">Rationale</a></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#design-outline">Design Outline</a></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#element-gardener-custom-metrics-provider-component">Element: Gardener Custom Metrics Provider Component</a><ul><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#high-availability-operation">High availability operation</a></li></ul></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#element-new-custom-pod-metric-for-shootkapis">Element: New Custom Pod Metric for ShootKapis</a></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#element-hpa">Element: HPA</a></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#element-vpa">Element: VPA</a></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#transition-strategy">Transition Strategy</a></li></ul></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#discussion-and-limitations">Discussion and Limitations</a><ul><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#gardener-custom-metrics-precludes-the-use-of-other-sources-of-custom-metrics">Gardener-custom metrics precludes the use of other sources of custom metrics</a></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#observed-fluctuations-in-actual-compute-efficiency-affecting-shootkapi-workloads">Observed fluctuations in actual compute efficiency affecting ShootKapi workloads</a></li></ul></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#alternatives">Alternatives</a></li><li><a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#references">References</a></li></ul></li></ul><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>When it comes to autoscaling shoot control plane <code>kube-apiserver</code> instances (ShootKapi hereafter), Gardener needs both stability and efficiency (accurate scaling). The existing approach of fusing HPA and VPA into the 2-dimensional autoscaler which is HVPA, poses severe algorithmic limitations which manifest as stability and efficiency issues in the field.</p><p>This document outlines the main deficiencies in the existing solution and proposes a simple design which overcomes them, reduces maintenance effort by reducing Gardener&#39;s custom code base, and enables subsequent reduction in ShootKapi compute cost.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Gardener uses a relatively complex approach for scaling shoot control plane <code>kube-apiserver</code> instances (ShootKapi). This need is a consequence of the following concerns:</p><ol><li>Gardener supplies K8s clusters of highly diverse compute scale and utilization - ranging from a couple of small practically idle nodes, to hundreds of heavily utilized giants. Furthermore, the ratio of &#39;cluster compute capacity&#39; to &#39;ShootKapi load&#39; substantially varies between different applications utilizing Gardener shoots. As a result, compute resources required by ShootKapis of different shoots vary by two orders of magnitude.</li><li>The compute cost of ShootKapi workloads constitutes a major part of Gardener&#39;s overall compute cost. Small relative waste in sizing ShootKapis results in considerable absolute cost.</li><li>Kube-apiserver does not scale well horizontally, in a sense that extra replicas come with substantial compute overhead.</li></ol><p>In short, ShootKapi needs to be scaled:</p><ul><li>Within a broad range</li><li>With reasonable accuracy, relative to actual resource consumption</li></ul><p>The implication is that ShootKapi requires both horizontal and vertical scaling. The existing implementation utilized to that end is <a href="https://github.com/gardener/hvpa-controller" target="_blank" rel="noreferrer">HVPA</a>.</p><h3 id="existing-solution" tabindex="-1">Existing Solution <a class="header-anchor" href="#existing-solution" aria-label="Permalink to &quot;Existing Solution&quot;">​</a></h3><p><a href="https://github.com/gardener/hvpa-controller" target="_blank" rel="noreferrer">HVPA</a> strives to achieve a fusion of HPA and VPA recommendations: <code>HvpaRecommendedCapacity = k * HpaRecommendedCapacity + (1 - k) * VpaRecommendedCapacity</code> The underlying goal is to allow HPA and VPA to be driven by the same CPU and memory usage metrics, and overcome the HPA-VPA incompatibility known to exist in that mode.</p><h3 id="deficiencies-of-the-existing-solution" tabindex="-1">Deficiencies of the Existing Solution <a class="header-anchor" href="#deficiencies-of-the-existing-solution" aria-label="Permalink to &quot;Deficiencies of the Existing Solution&quot;">​</a></h3><p>There are <a href="https://github.com/gardener/hvpa-controller/blob/08b69b947b93cc054eb3476e2ab7479860a08acd/docs/KnownIssues.md" target="_blank" rel="noreferrer">known issues in the scaling algorithm implemented by HVPA</a>. Those substantially restrict the set of features which can be used with the level of reliability required in productive applications. The issues primarily manifest as the following practical problems:</p><ul><li>To ensure correct operation, HVPA must be configured to do horizontal scaling first: vertical scale is maintained at its minimum, unless horizontal scale has reached its maximum. This results in higher number of replicas than strictly necessary, wasting resources.<sup>[<a href="https://github.com/gardener/hvpa-controller/blob/08b69b947b93cc054eb3476e2ab7479860a08acd/docs/KnownIssues.md#inefficiency-induced-by-initial-horizontal-only-scaling-stage" target="_blank" rel="noreferrer">1</a>]</sup></li><li>To mitigate further waste per previous point, HVPA must be limited to a low number of replicas. That limit is inadequate for some applications. Furthermore, the current value of the limit (4) is a poor fit for high availability applications which often use 3 availability zones, resulting in uneven replica distribution across zones.</li><li>HVPA uses a stabilisation mechanism which suppresses scaling until a certain &#39;MinChange&#39; threshold is reached. This behaviour is known to prevent the proper response to node CPU exhaustion.<sup>[<a href="https://github.com/gardener/hvpa-controller/blob/08b69b947b93cc054eb3476e2ab7479860a08acd/docs/KnownIssues.md#minchange-stabilisation-prevents-response-to-node-cpu-exhaustion" target="_blank" rel="noreferrer">2</a>]</sup></li><li>HVPA does not make use of the opportunity to update a pod&#39;s vertical scale when the pod is created. HVPA can only update a pod by purposefully evicting all replicas. This results in a greater number of pod evictions.</li><li>HVPA lacks proper hysteresis support and may make unintended updates to the target.<sup>[<a href="https://github.com/gardener/hvpa-controller/blob/08b69b947b93cc054eb3476e2ab7479860a08acd/docs/KnownIssues.md#algorithmic-limitation-fusing-the-behavior-of-two-blackbox-systems" target="_blank" rel="noreferrer">3</a>]</sup></li><li>HVPA gets stuck in a state with small number of large replicas in some sutuations in which large replicas are unnecessary.<sup>[<a href="https://github.com/gardener/hvpa-controller/blob/08b69b947b93cc054eb3476e2ab7479860a08acd/docs/KnownIssues.md#hvpa-stuck-in-unintended-stable-equilibrium-due-to-feedback-of-non-deterministic-replica-count-signal" target="_blank" rel="noreferrer">4</a>]</sup></li></ul><h3 id="other-benefits-to-replacing-the-existing-solution" tabindex="-1">Other Benefits to Replacing the Existing Solution <a class="header-anchor" href="#other-benefits-to-replacing-the-existing-solution" aria-label="Permalink to &quot;Other Benefits to Replacing the Existing Solution&quot;">​</a></h3><p>HVPA applies recommendations via direct edits to the controlled object (e.g. <code>Deployment</code>). This approach requires nonobvious special handling by Gardener code outside HVPA, which is error-prone.</p><h3 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h3><ul><li>Improve ShootKapi autoscaling stability by eliminating the stability issues existing in the current HVPA-based solution.</li><li>Improve ShootKapi operational efficiency at low application load levels, by avoiding excessive replicas driven by HVPA&#39;s policy for early horizontal scale-out.</li><li>Allow usage of VPA for right-sizing the resource requests during the entire time and not only under certain conditions.</li><li>Enable future migration away from HVPA by removing all dependency on it for scaling ShootKapi.</li><li>Reduce Gardener custom code base and ongoing maintenance effort.</li></ul><h3 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-Goals&quot;">​</a></h3><p>There are other components currently scaled via HVPA. Changing the autoscaling mode of these, and of <code>kube-apiserver</code>s other than the one in the shoot control plane, is outside the scope of this GEP. These workloads are subject to a different mode of autoscaling (e.g. vertical-only, where HVPA is only used to stabilize VPA behavior), and it is advantageous from project execution perspective to address them as a separate concern.</p><p>The scaling approach hereby proposed may be suitable for scaling the <code>virtual-garden-kube-apiserver</code> and <code>gardener-apiserver</code> components, which are part of the virtual garden cluster control plane. Scaling those components is outside the scope of this GEP.</p><h2 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h2><p>ShootKapi HVPA is replaced by individual HPA and VPA. Undesirable interference between HPA and VPA is avoided through the use of sufficiently independent driving signals. HPA is driven by the rate of HTTP requests to kube-apiserver. VPA is driven by CPU and memory usage metrics.</p><h3 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h3><p>A rough, heuristic horizontal sizing sets the stage for optimal VPA operation (horizontal size is within stable and reasonably efficient range). Vertical scaling fine-tunes requests, ensuring high efficiency (requests not too high) and stability (requests not too low).</p><h3 id="design-outline" tabindex="-1">Design Outline <a class="header-anchor" href="#design-outline" aria-label="Permalink to &quot;Design Outline&quot;">​</a></h3><p>One HPA and one VPA resources are deployed alongside each ShootKapi deployment object. The VPA controls CPU and memory requests but not limits. The HPA is driven by the average rate of API requests per pod of the target kube-apiserver deployment.</p><p>A new component named gardener-custom-metrics is deployed on each seed. It directly scrapes metrics data from all ShootKapi pods on the seed and derives custom metrics based on it. The component is registered as an extension API service to the seed kube-apiserver. It occupies the custom metrics API extension point and is responsible for providing all custom metrics for the seed kube-apiserver, including the one driving the ShootKapi HPA.</p><p><img src="'+a+'" alt="Design outline" title="Design outline"></p><p><em>Fig 2: Proposed design</em></p><h3 id="element-gardener-custom-metrics-provider-component" tabindex="-1">Element: Gardener Custom Metrics Provider Component <a class="header-anchor" href="#element-gardener-custom-metrics-provider-component" aria-label="Permalink to &quot;Element: Gardener Custom Metrics Provider Component&quot;">​</a></h3><p>A new component, named gardener-custom-metrics is added to seed clusters. It periodically scrapes the metrics endpoints of all ShootKapi pods on the seed. It implements the K8s custom metrics API and provides K8s metrics specific to Gardener, based on custom calculations. The proposed design can naturally be extended to multiple sources of input data and a non-volatile cache for acquired data. However, in the scope of this proposal, the only data source is the aforementioned metrics scrape, and the calculated values only need to be briefly cached in memory.</p><p>A kube-apiserver&#39;s metrics response measures megabytes in size. To reduce the amount of network traffic, this proposal utilizes compressed HTTP responses when scraping metrics. Outside the scope of this proposal, a future enhancement is possible, in which a metrics filter component is added as a sidecar to each ShootKapi pod. Each such sidecar would mirror the metrics endpoint of its respective ShootKapi, with the only addition of support for filtering based on an HTTP request parameter (e.g. <code>GET /metrics?name=apiserver_request_total</code> would forward a <code>GET /metrics</code> request to the ShootKapi, and then would reduce the response to only <code>apiserver_request_total</code> counters, before passing it on to the caller).</p><h4 id="high-availability-operation" tabindex="-1">High availability operation <a class="header-anchor" href="#high-availability-operation" aria-label="Permalink to &quot;High availability operation&quot;">​</a></h4><p>A single gardener-custom-metrics replica does not satisfy Gardener&#39;s high availability (HA) requirements. Autoscaling operations can tolerate brief (1-2 minutes) periods of metrics signal outage without disruption to autoscaling service availability. However, node provisioning delays easily exceed that tolerable amount, and do not allow timely fail over via creation of a new replica after the existing one fails.</p><p>For a seed in high availability mode, gardener-custom-metrics is deployed in a multi-replica active/passive arrangement, based on the well established controller leader election mechanism used by other Gardener components. Passive replicas do not respond to metrics requests. Consumers access gardener-custom-metrics through a K8s service which routes all metrics requests to the one active replica. That service does not use a selector and endpoints are managed by gardener-custom-metrics itself. At any time there is at most one endpoint. When a gardener-custom-metrics replica acquires leadership, as part of the transition from passive to active state, the replica configures the service with a single endpoint which points to its own metrics server IP endpoint.</p><p>Since gardener-custom-metrics replicas do not interfere with each other, an active/passive arrangement is not necessitated by functional requirements. A simpler active/active is technically possible, but pragmatically undesirable due to the substantial amount of cross availability zone network traffic each active replica generates.</p><h3 id="element-new-custom-pod-metric-for-shootkapis" tabindex="-1">Element: New Custom Pod Metric for ShootKapis <a class="header-anchor" href="#element-new-custom-pod-metric-for-shootkapis" aria-label="Permalink to &quot;Element: New Custom Pod Metric for ShootKapis&quot;">​</a></h3><p>A new <code>shoot:apiserver_request_total:rate</code> pod custom metric is made available for each ShootKapi pod on the seed. It is provided by the gardener-custom-metrics component. It is the rate of API requests per second, broken down by ShootKapi pod.</p><h3 id="element-hpa" tabindex="-1">Element: HPA <a class="header-anchor" href="#element-hpa" aria-label="Permalink to &quot;Element: HPA&quot;">​</a></h3><p>ShootKapi is scaled horizontally via HPA operating on the aforementioned average kube-apiserver request rate custom metric. Scale-in is delayed by a stabilization window. This avoids unnecessary flapping, the effects of which would be further amplified by VPA-driven evictions, and serves as a general precaution against HPA-VPA resonance, by ensuring that the two autoscalers operate with different frequency.</p><p>The scaling threshold value for HPA is initially set to a conservative (lower-biased) estimate of the requests/replica ratio observed with the existing solution. It will be then gradually fine-tuned to the maximum value which does not impact quality of service.</p><p>This proposal is the first stage of an incremental, two stage approach. It aims primarily at resolving the existing stability issues inherent to HVPA and enabling (but not executing) scaling efficiency optimizations. The second stage will be focused solely on further fine-tuning scaling efficiency to optimize ShootKapi compute cost over HVPA. Details follow in the <a href="/docs/proposals/0023-autoscaling-kube-apiserver-via-independent-hpa-and-vpa/readme/#discussion-and-limitations">Discussion and Limitations</a> section.</p><h3 id="element-vpa" tabindex="-1">Element: VPA <a class="header-anchor" href="#element-vpa" aria-label="Permalink to &quot;Element: VPA&quot;">​</a></h3><p>A standard VPA operates on ShootKapi. Its primary purpose is to improve resource efficiency over what&#39;s possible via HPA&#39;s coarse, replica-granularity scaling, by shrinking replicas down to match actual utilization.</p><p>This improves over the existing solution by having vertical scaling active the entire time and not only during certain periods.</p><h3 id="transition-strategy" tabindex="-1">Transition Strategy <a class="header-anchor" href="#transition-strategy" aria-label="Permalink to &quot;Transition Strategy&quot;">​</a></h3><p>The following steps will be executed over time, and provide a non-disruptive transition from the existing implementation to the one hereby proposed.</p><ol><li>Proposed scaling approach will be deployed behind a feature gate and disabled by default. Existing HVPA feature flag will be preserved at this point, as its use is not limited to kube-apiserver scaling.</li><li>New feature gate gradually enabled until all ShootKapi workloads scaled by new approach (Note: this step applies to individual garden/seed instances, and not to the code base as a whole).</li><li>At this point, the preexisting HVPA feature flag has no effects on ShootKapi scaling (Note: this step applies to individual garden/seed instances, and not to the code base as a whole).</li><li>New feature flag promoted and eventually removed.</li><li>(Outside the scope of this proposal) Use of HVPA removed for other workloads and the preexisting HVPA flag removed.</li></ol><p>During step 2, the following quantities will be used to evaluate the fitness of the new autoscaling method. Unless specified otherwise, &quot;resources&quot; refers to memory and CPU:</p><ul><li>Resource utilisation: how much of the requested resources are actually being used</li><li>Insufficient resource requests: how often do the resources used by ShootKapi exceed what the autoscaler requested</li><li>Number of eviction events</li><li>Number of ShootKapi replicas: lower replica count is preferred, as it promotes object cache reuse</li></ul><p>The following quantities are also useful, but their accuracy varies greatly, depending on the influence of uncontrolled variables. They are proposed for opportunistic use at the discretion of the persons performing the evaluation.</p><ul><li>Total resource used by ShootKapi pods</li><li>Total resource requested by ShootKapi pods</li><li>API response latency</li><li>Node count</li><li>Number of HTTP error 429 events</li></ul><h2 id="discussion-and-limitations" tabindex="-1">Discussion and Limitations <a class="header-anchor" href="#discussion-and-limitations" aria-label="Permalink to &quot;Discussion and Limitations&quot;">​</a></h2><p>Overall, multidimensional autoscaling is a job which cannot be accomplished efficiently with the one-dimensional autoscalers currently available in the K8s ecosystem. The proposed approach is a compromise which relies on estimating actual compute resource demand based on an application metric (API request rate). Such estimate is inherently inaccurate, creating a need for a safety margin (excess replicas), and a risk of resource exhaustion under highly unusual application loads.</p><h4 id="gardener-custom-metrics-precludes-the-use-of-other-sources-of-custom-metrics" tabindex="-1">Gardener-custom metrics precludes the use of other sources of custom metrics <a class="header-anchor" href="#gardener-custom-metrics-precludes-the-use-of-other-sources-of-custom-metrics" aria-label="Permalink to &quot;Gardener-custom metrics precludes the use of other sources of custom metrics&quot;">​</a></h4><p>With current K8s design, only one API extension can serve custom metrics. Per this GEP, the custom metrics extension point is occupied by gardener-custom-metrics. If necessary in the future, this limitation can be mitigated via gardener-custom-metrics aggregating other sources of custom metrics, and selectively forwarding queries to them.</p><h4 id="observed-fluctuations-in-actual-compute-efficiency-affecting-shootkapi-workloads" tabindex="-1">Observed fluctuations in actual compute efficiency affecting ShootKapi workloads <a class="header-anchor" href="#observed-fluctuations-in-actual-compute-efficiency-affecting-shootkapi-workloads" aria-label="Permalink to &quot;Observed fluctuations in actual compute efficiency affecting ShootKapi workloads&quot;">​</a></h4><p>There is a known source of horizontal scaling inefficiency, which presents an opportunity for substantial further improvement. It is not addressed by this proposal and instead deferred to a separate implementation stage, as it requires a strictly incremental effort on top of this GEP.</p><p>An approximate 50% reduction (factor 0.5) of the effective compute power per unit of CPU was occasionally observed on some productive ShootKapi instances. The change occurs with a quick cutoff transition, and has been observed for periods or up to 2 hours. This variance currently forces substantial safety margin upon HPA&#39;s target metric value, effectively necessitating more replicas to be deployed than required during usual operation.</p><p>The source is believed to be competition for compute resources with sibling workloads, either on the K8s, or infrastructure level, but the circumstances have not been conductive to investigation after the fact. A subsequent stage, outside the scope of this GEP is planned to focus on understanding the root cause, and further optimizing HPA&#39;s target metric value accordingly.</p><p>Once this biggest source of inefficiency has been resolved, yet another round of scaling performance fine-tuning is planned, where instead of overall request rate, HPA will be driven by a weighted average, reflecting the different compute cost of different request categories (e.g. a cluster-scoped LIST is more cpu intensive than a resource-scoped PUT).</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to &quot;Alternatives&quot;">​</a></h2><p>Below is a list of the most promising alternatives to the proposed approach.</p><ol><li><strong>Using VPA, plus a simple custom horizontal autoscaler which acts when VPA recommendation goes below or above a predetermined acceptable range:</strong> Initial research indicates to be a promising solution. The solution described in this GEP was ultimately preferred because it does not require building custom components.</li><li><strong>Adding the missing stabilization features to VPA via a custom recommender which is a minimal fork of the default VPA recommender:</strong> Not a standalone solution, but a potential part of any solution which leverages VPA but requires less disruptive scaling behavior. Research indicates to be a pragmatically viable solution, incurring minimal ongoing maintenance cost.</li></ol><p>Continued use of (an improved) HVPA does not look promising, due to the inherent algorithmic issues described above.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://github.com/gardener/hvpa-controller" target="_blank" rel="noreferrer">HVPA</a></li><li><a href="https://github.com/gardener/hvpa-controller/blob/08b69b947b93cc054eb3476e2ab7479860a08acd/docs/KnownIssues.md" target="_blank" rel="noreferrer">Known issues in the scaling algorithm implemented by HVPA</a></li><li>[<a href="https://github.com/gardener/hvpa-controller/blob/08b69b947b93cc054eb3476e2ab7479860a08acd/docs/KnownIssues.md#inefficiency-induced-by-initial-horizontal-only-scaling-stage" target="_blank" rel="noreferrer">1</a>]: Known Issues in HVPA Behaviour - Inefficiency induced by initial horizontal-only scaling stage</li><li>[<a href="https://github.com/gardener/hvpa-controller/blob/08b69b947b93cc054eb3476e2ab7479860a08acd/docs/KnownIssues.md#minchange-stabilisation-prevents-response-to-node-cpu-exhaustion" target="_blank" rel="noreferrer">2</a>]: Known Issues in HVPA Behaviour - &#39;MinChange&#39; stabilisation prevents response to node CPU exhaustion</li><li>[<a href="https://github.com/gardener/hvpa-controller/blob/08b69b947b93cc054eb3476e2ab7479860a08acd/docs/KnownIssues.md#algorithmic-limitation-fusing-the-behavior-of-two-blackbox-systems" target="_blank" rel="noreferrer">3</a>]: Known Issues in HVPA Behaviour - Algorithmic limitation: fusing the behavior of two blackbox systems</li><li>[<a href="https://github.com/gardener/hvpa-controller/blob/08b69b947b93cc054eb3476e2ab7479860a08acd/docs/KnownIssues.md#hvpa-stuck-in-unintended-stable-equilibrium-due-to-feedback-of-non-deterministic-replica-count-signal" target="_blank" rel="noreferrer">4</a>]: Known Issues in HVPA Behaviour - HVPA stuck in unintended stable equilibrium due to feedback of non-deterministic &quot;replica count&quot; signal</li></ul>',74)]))}const b=i(n,[["render",r]]);export{f as __pageData,b as default};
